import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingController {

    /**
     * The sheet's settings as the screen shows them; the clerk limit has two decimals, null when none,
     * and so has the floor; the terms are in days, and so are gradeTerms, by grade, for each grade with
     * its own; the late percent has two decimals; the policy date
     * is null when blank (the sheet's today), and so is the period numbering from (off); the cap has
     * two decimals, null when none.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, List<RoleView> roles, Map<String, Integer> gradeTerms, String cap) {}

    /** A user name's role, as clerk or steward. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole r) {
            return new RoleView(r.getUserName(), r.getRole().label());
        }
    }

    /** A clerk limit with at most two decimals; blank or null: no limit. */
    public record ClerkLimitRequest(@Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String value) {

        BigDecimal limitValue() {
            return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
        }
    }

    /** A cap with at most two decimals; blank or null: none. */
    public record CapRequest(@Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String value) {

        BigDecimal capValue() {
            return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
        }
    }

    /** A floor with at most two decimals. */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String value) {

        BigDecimal floorValue() {
            return new BigDecimal(value).setScale(2);
        }
    }

    /** A late percent with at most two decimals. */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String value) {

        BigDecimal latePctValue() {
            return new BigDecimal(value).setScale(2);
        }
    }

    /** A policy date (yyyy-mm-dd); blank or null: the sheet's today. */
    public record PolicyDateRequest(@Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String value) {

        LocalDate policyDateValue() {
            return value == null || value.isEmpty() ? null : LocalDate.parse(value);
        }
    }

    /** A period numbering from date (yyyy-mm-dd); blank or null: off. */
    public record PeriodNumberingFromRequest(@Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String value) {

        LocalDate fromValue() {
            return value == null || value.isEmpty() ? null : LocalDate.parse(value);
        }
    }

    /** Terms: a whole number of days. */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\d{1,4}") String value) {

        int termsValue() {
            return Integer.parseInt(value);
        }
    }

    /** A role: clerk or steward. */
    public record RoleRequest(@NotNull @Pattern(regexp = "clerk|steward") String role) {

        Role roleValue() {
            return Role.valueOf(role.toUpperCase());
        }
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView get(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new SettingsView(text(service.clerkLimit(sheetId)), text(service.floor(sheetId)),
                service.terms(sheetId), text(service.latePct(sheetId)), service.policyDate(sheetId),
                service.periodNumberingFrom(sheetId),
                service.roles(sheetId).stream().map(RoleView::of).toList(), service.gradeTerms(sheetId),
                text(service.cap(sheetId)));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClerkLimitRequest request) {
        service.setClerkLimit(sheetId, user, request.limitValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/floor")
    public SettingsView setFloor(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid FloorRequest request) {
        service.setFloor(sheetId, user, request.floorValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/terms")
    public SettingsView setTerms(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        service.setTerms(sheetId, user, request.termsValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/terms/{grade}")
    public SettingsView setGradeTerms(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        service.setGradeTerms(sheetId, user, grade, request.termsValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/late-pct")
    public SettingsView setLatePct(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid LatePctRequest request) {
        service.setLatePct(sheetId, user, request.latePctValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/policy-date")
    public SettingsView setPolicyDate(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PolicyDateRequest request) {
        service.setPolicyDate(sheetId, user, request.policyDateValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PeriodNumberingFromRequest request) {
        service.setPeriodNumberingFrom(sheetId, user, request.fromValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/cap")
    public SettingsView setCap(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid CapRequest request) {
        service.setCap(sheetId, user, request.capValue());
        return get(sheetId, user);
    }

    @PutMapping("/roles/{name}")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) String name,
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RoleRequest request) {
        return RoleView.of(service.setRole(sheetId, user, name, request.roleValue()));
    }

    private static String text(BigDecimal limit) {
        return limit == null ? null : limit.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Map;
import java.util.TreeMap;

/** A sheet, keyed by the id a user types; everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's today: every date decision and default date on the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number given on the sheet; the next claim opened takes the one after it. */
    @Column(name = "last_claim_number", nullable = false)
    private long lastClaimNumber;

    /** A clerk can settle a claim only when its due is at or below it; null means no limit. */
    @Column(name = "clerk_limit", precision = 14, scale = 2)
    private BigDecimal clerkLimit;

    /** A claim's live due is at least it; a settled or stated figure is not moved by it. */
    @Column(name = "due_floor", nullable = false, precision = 14, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** The terms in days: a claim's due-by is its date plus them. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    /** The terms set for a grade, by grade; a grade without its own uses {@link #terms}. */
    @ElementCollection
    @CollectionTable(name = "sheet_grade_terms", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "grade")
    @Column(name = "terms", nullable = false)
    private Map<String, Integer> gradeTerms = new TreeMap<>();

    /** The late percent: an overdue claim's due gains it of its figure for every full 30 days overdue. */
    @Column(name = "late_pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal latePct = new BigDecimal("0.00");

    /** A claim dated before it rounds half up, one on or after it half to even; null means the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** While set and today is on or after it, a claim opened is numbered within its period; null means off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** A person's due-total is at most it; null means none. */
    @Column(name = "due_cap", precision = 14, scale = 2)
    private BigDecimal cap;

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() { return id; }

    public String getCreatedBy() { return createdBy; }

    public Instant getCreatedAt() { return createdAt; }

    public LocalDate getToday() { return today; }

    public void setToday(LocalDate today) { this.today = today; }

    public BigDecimal getClerkLimit() { return clerkLimit; }

    public void setClerkLimit(BigDecimal clerkLimit) { this.clerkLimit = clerkLimit; }

    public BigDecimal getFloor() { return floor; }

    public void setFloor(BigDecimal floor) { this.floor = floor; }

    public BigDecimal getCap() { return cap; }

    public void setCap(BigDecimal cap) { this.cap = cap; }

    /** The due-total, at most the cap; null (n/a) stays null. */
    public BigDecimal capped(BigDecimal dueTotal) {
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    public int getTerms() { return terms; }

    public void setTerms(int terms) { this.terms = terms; }

    /** The terms set for the grade; null when it has none of its own. */
    public Integer getGradeTerms(String grade) { return gradeTerms.get(grade); }

    public void setGradeTerms(String grade, int terms) { gradeTerms.put(grade, terms); }

    /** The terms a claim of the grade is given: its own, else the sheet's. */
    public int termsFor(String grade) { return gradeTerms.getOrDefault(grade, terms); }

    public BigDecimal getLatePct() { return latePct; }

    public void setLatePct(BigDecimal latePct) { this.latePct = latePct; }

    public LocalDate getPolicyDate() { return policyDate; }

    public void setPolicyDate(LocalDate policyDate) { this.policyDate = policyDate; }

    public LocalDate getPeriodNumberingFrom() { return periodNumberingFrom; }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) { this.periodNumberingFrom = periodNumberingFrom; }

    /** Whether a claim opened now is numbered within its period rather than sheet-wide. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** Take the next claim number on the sheet. */
    public long nextClaimNumber() { return ++lastClaimNumber; }
}

