package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A claim by a person on a sheet: an amount (two decimals), a date, a note and a status (DRAFT when
 * added), and a number and who opened it once opened. A negative amount makes it a correction, which
 * names the number of the SETTLED claim of its person that it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /**
     * Its place in its sheet's list, newest (highest) first: the next of claim_listed_seq, given by the
     * store when added and again when moved to another person.
     */
    @Column(name = "listed", insertable = false)
    private Long listed;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    /** The date it is due by, fixed when added: its date plus the terms of its person's grade then. */
    @Column(name = "due_by", nullable = false, updatable = false)
    private LocalDate dueBy;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /**
     * Given when the claim is opened: the sheet-wide number, or <period name>-<n> (X-<n> in no
     * period) while the sheet numbers by period; none while DRAFT, kept when VOID.
     */
    @Column(name = "claim_number")
    private String number;

    /** The period the claim was numbered within (empty: in no period); none unless numbered by period. */
    @Column(name = "number_period")
    private String numberPeriod;

    /** The claim's place in its period's numbering; none unless numbered by period. */
    @Column(name = "number_seq")
    private Integer numberSeq;

    /** The user who opened the claim; none while DRAFT. */
    @Column(name = "opened_by", length = 100)
    private String openedBy;

    /** The due fixed when the claim was settled; none while not settled, or settled with no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Bound by its person's last statement, which it counted toward; its due is then {@link #statedDue}. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due it had at its person's last statement; none while not stated, or stated with no due. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this correction corrects; none unless a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** Its status log, oldest first: a line for each status it has had, DRAFT when added. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimLogEntry> log = new ArrayList<>();

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.dueBy = dueBy;
    }

    public Long getId() { return id; }

    /** A correction: a negative amount. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }

    public String getCorrects() { return corrects; }

    public void setCorrects(String corrects) { this.corrects = corrects; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public Long getListed() { return listed; }

    /** Move the claim to another person, listed as their newest at the given place in the list. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
    }

    public BigDecimal getAmount() { return amount; }

    public void setAmount(BigDecimal amount) { this.amount = amount; }

    public LocalDate getDate() { return date; }

    public void setDate(LocalDate date) { this.date = date; }

    public String getNote() { return note; }

    /** The date it is due by, fixed when added; it does not move with its date or the terms. */
    public LocalDate getDueBy() { return dueBy; }

    public void setNote(String note) { this.note = note; }

    public ClaimStatus getStatus() { return status; }

    public void setStatus(ClaimStatus status) { this.status = status; }

    public List<ClaimLogEntry> getLog() { return Collections.unmodifiableList(log); }

    /** Log the status it now has, given by the user on the date, with its due at that moment. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogEntry(status, by, on, due));
    }

    public String getNumber() { return number; }

    /** Number the claim sheet-wide. */
    public void setNumber(long number) { this.number = String.valueOf(number); }

    /** Number the claim within a period (empty name: in no period): <period name>-<n>, or X-<n>. */
    public void setNumberWithin(String period, int seq) {
        this.numberPeriod = period;
        this.numberSeq = seq;
        this.number = (period.isEmpty() ? "X" : period) + "-" + seq;
    }

    public String getOpenedBy() { return openedBy; }

    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public BigDecimal getSettledDue() { return settledDue; }

    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }

    public boolean isStated() { return stated; }

    public BigDecimal getStatedDue() { return statedDue; }

    /**
     * Whether its due is now bound by its person's last statement: stated and not PENDING. A PENDING
     * claim shows its live due, and is bound again if rejected.
     */
    public boolean isBound() { return stated && status != ClaimStatus.PENDING; }

    /** Bind the claim to a due (null: it has none), as its person's statement does. */
    public void state(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Leave the claim unbound, its due live again. */
    public void unstate() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * The late charge on an overdue claim: the sheet's late percent of its figure (the due bound by a
 * statement, else its floored live due) for every full 30 days past its due-by, rounded to cents like
 * its due ({@link Rounding}). A correction has none. It is never bound by a statement; settling freezes it into the settled due.
 */
public final class LateCharge {

    /** The days in each step of the charge. */
    private static final int STEP_DAYS = 30;

    private LateCharge() {}

    /** Overdue: OPEN (or PENDING) with its due-by (fixed when it was added) before the sheet's today. */
    public static boolean isOverdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today);
    }

    /** The charge on the claim with the given figure (null: none) as of today; zero when not overdue or a correction. */
    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        BigDecimal zero = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection() || !isOverdue(claim, today)) return zero;
        long steps = ChronoUnit.DAYS.between(claim.getDueBy(), today) / STEP_DAYS;
        return figure.multiply(latePct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
                .setScale(2, rounding);
    }

    /**
     * The figure with the charge it would have on top were the claim open now, whatever its status; null
     * when the figure is.
     */
    public static BigDecimal withChargeAsOpen(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        if (figure == null || claim.isCorrection() || today == null || !claim.getDueBy().isBefore(today)) {
            return figure;
        }
        long steps = ChronoUnit.DAYS.between(claim.getDueBy(), today) / STEP_DAYS;
        return figure.add(figure.multiply(latePct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
                .setScale(2, rounding));
    }

    /** The figure with its charge added on top; null when the figure is. */
    public static BigDecimal withCharge(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        return figure == null ? null : figure.add(of(claim, figure, today, latePct, rounding));
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * How a claim's live figures (the rate step and the late charge) round to cents: half up when the
 * claim is dated before the sheet's policy date (none: the sheet's today), else half to even. A
 * correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    private Rounding() {}

    /** The date a claim rounds by: a correction's corrected claim's date (from {@code datesByNumber}), else its own. */
    public static LocalDate basisOf(Claim claim, Map<String, LocalDate> datesByNumber) {
        if (claim.getCorrects() != null) {
            LocalDate corrected = datesByNumber.get(claim.getCorrects());
            if (corrected != null) return corrected;
        }
        return claim.getDate();
    }

    /** The rounding of a claim rounding by the given date. */
    public static RoundingMode of(LocalDate basis, LocalDate policyDate, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return policy != null && basis.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The dates of the numbered claims, by number. */
    public static Map<String, LocalDate> datesByNumber(List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim c : claims) {
            if (c.getNumber() != null) dates.put(c.getNumber(), c.getDate());
        }
        return dates;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
 * sheet's claimed-total and due-total, each person's at most the sheet's cap; an overdue claim's due has its {@link LateCharge} on top. A change takes a {@link #snapshot} before it alters
 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
 * lines, a ROLLUP line for each person whose figures (overdue-total included) moved (in the order
 * they were added) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** A person's figures; a null due-total is n/a; the overdue-total is the dues of their overdue claims. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(dueTotal, other.dueTotal)
                    && overdueTotal.compareTo(other.overdueTotal) == 0;
        }
    }

    /** The sheet's figures at a moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Locks the sheet until the caller's transaction ends, so no other
     * change on the sheet moves the figures between this snapshot and the one after the change.
     */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        BigDecimal floor = sheet == null ? zero() : sheet.getFloor();
        BigDecimal latePct = sheet == null ? zero() : sheet.getLatePct();
        LocalDate policyDate = sheet == null ? null : sheet.getPolicyDate();
        Map<String, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(all);
        for (Claim claim : all) {
            if (claim.getStatus().counts()) {
                claimsByPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        BigDecimal overdueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean fixed = false;
            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
                if (!person.counts(claim)) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
